input.command:
for f in $(find /root/autodl-tmp/vla-ssd/results/bootstrap_r2/ -name "*.json" | sort); do echo "=== $f ==="; python3 -c "
import json
with open('$f') as fh:
    d = json.load(fh)
    pr2 = d.get('peak_r2', '?')
    pl = d.get('peak_layer', '?')
    er2 = d.get('exit_r2', '?')
    el = d.get('exit_layer', '?')
    delta = d.get('delta', '?')
    ci = d.get('ci_95', d.get('ci95', d.get('bootstrap_ci95', ['?','?'])))
    nb = d.get('n_bootstrap', d.get('n_bootstraps', '?'))
    if isinstance(pr2, float): print(f'Peak R2={pr2:.4f} @ L{pl}')
    else: print(f'Peak R2={pr2} @ L{pl}')
    if isinstance(er2, float): print(f'Exit R2={er2:.4f} @ L{el}')
    else: print(f'Exit R2={er2} @ L{el}')
    if isinstance(delta, float): print(f'Delta={delta:.4f}')
    else: print(f'Delta={delta}')
    if isinstance(ci[0], (int,float)): 
        print(f'CI95=[{ci[0]:.4f}, {ci[1]:.4f}]')
        print(f'Significant={ci[0] > 0}')
    else:
        print(f'CI95={ci}')
    print(f'n_bootstrap={nb}')
" 2>&1; done

